import{_ as l,C as r,o as n,c as s,j as d,a as e,E as o,a5 as c}from"./chunks/framework.BYIUCCsM.js";const v=JSON.parse('{"title":"标签页","description":"","frontmatter":{},"headers":[],"relativePath":"components/tabs.md","filePath":"components/tabs.md","lastUpdated":1787953591000}'),h={name:"components/tabs.md"},b={id:"标签页",tabindex:"-1"};function g(u,t,p,x,f,m){const i=r("Badge"),a=r("XhDemo");return n(),s("div",null,[d("h1",b,[t[0]||(t[0]=e("标签页 ",-1)),o(i,{type:"info",text:"tabs"}),t[1]||(t[1]=e()),t[2]||(t[2]=d("a",{class:"header-anchor",href:"#标签页","aria-label":'Permalink to "标签页 <Badge type="info" text="tabs" />"'},"​",-1))]),t[3]||(t[3]=c('<p>在同一块区域里切换几组并列的内容，同时只显示一组。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>内容属于同一个对象的不同侧面（详情 / 权限 / 日志），用户会来回看。</li><li>各组内容量相当，且不需要同时对照。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>各组需要同时看见或互相对照：并排摆，别切换。</li><li>有先后顺序、必须走完：用<a href="./steps">步骤条</a>。</li><li>只是切换一个显示开关：用<a href="./toggle-group">切换按钮组</a>。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li><code>activationMode</code> 决定方向键移动焦点时是否顺带切换：内容加载昂贵时改 <code>manual</code>，方向键只搬焦点、按 Enter 才切。</li><li><code>variant</code> 三档（<code>line</code> / <code>card</code> / <code>segment</code>）只改选中态怎么画，切换行为与键盘操作三档一致。</li><li>面板常挂，靠 <code>hidden</code> 显隐。</li><li><code>root</code> 按书写顺序渲染子节点：把面板写在标签栏前面，标签栏就落到内容之后。</li><li><code>reorderable</code> 打开后标签可以拖着换位，键盘走 Alt + 主轴方向键。<strong>只给 <code>collection</code> 时代铺的那套标记里没有播报区与拖动把手</strong>：要读屏播报与触屏拖动，得写默认插槽并自己渲 <code>live-region</code> 与 <code>tab-drag-trigger</code>。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>default-value 指定初始选中项，禁用的标签方向键会跳过；面板常挂，靠 hidden 显隐</p>',10)),o(a,{src:"tabs/01-basic"}),t[4]||(t[4]=d("h3",{id:"受控",tabindex:"-1"},[e("受控 "),d("a",{class:"header-anchor",href:"#受控","aria-label":'Permalink to "受控"'},"​")],-1)),t[5]||(t[5]=d("p",null,"传了 value 就由宿主说了算，组件自己不再改选中值；切换意图从 value-change 出来，写回才真的切",-1)),o(a,{src:"tabs/02-controlled"}),t[6]||(t[6]=d("h3",{id:"手动激活",tabindex:"-1"},[e("手动激活 "),d("a",{class:"header-anchor",href:"#手动激活","aria-label":'Permalink to "手动激活"'},"​")],-1)),t[7]||(t[7]=d("p",null,'activation-mode="manual" 时方向键只搬焦点，按 Enter 或空格才真的切面板',-1)),o(a,{src:"tabs/03-manual"}),t[8]||(t[8]=d("h3",{id:"竖排",tabindex:"-1"},[e("竖排 "),d("a",{class:"header-anchor",href:"#竖排","aria-label":'Permalink to "竖排"'},"​")],-1)),t[9]||(t[9]=d("p",null,"orientation 换掉方向键收哪一对键：竖排认上下键，左右键原样放行给页面",-1)),o(a,{src:"tabs/04-vertical"}),t[10]||(t[10]=d("h3",{id:"形态",tabindex:"-1"},[e("形态 "),d("a",{class:"header-anchor",href:"#形态","aria-label":'Permalink to "形态"'},"​")],-1)),t[11]||(t[11]=d("p",null,"variant 只改选中态怎么画，切换行为与键盘操作三档一致；不写 variant 即 line 档",-1)),o(a,{src:"tabs/05-variant"}),t[12]||(t[12]=d("h3",{id:"语气",tabindex:"-1"},[e("语气 "),d("a",{class:"header-anchor",href:"#语气","aria-label":'Permalink to "语气"'},"​")],-1)),t[13]||(t[13]=d("p",null,"tone 决定选中态用哪族颜色，与 variant 正交；这里固定 card 形态只看语气的差别",-1)),o(a,{src:"tabs/06-tone"}),t[14]||(t[14]=d("h3",{id:"尺寸",tabindex:"-1"},[e("尺寸 "),d("a",{class:"header-anchor",href:"#尺寸","aria-label":'Permalink to "尺寸"'},"​")],-1)),t[15]||(t[15]=d("p",null,"size 换标签的高度、内边距与字号，不传 size 即默认档",-1)),o(a,{src:"tabs/07-size"}),t[16]||(t[16]=d("h3",{id:"标签栏前后缀",tabindex:"-1"},[e("标签栏前后缀 "),d("a",{class:"header-anchor",href:"#标签栏前后缀","aria-label":'Permalink to "标签栏前后缀"'},"​")],-1)),t[17]||(t[17]=d("p",null,"list 里只收 trigger；要在标签栏两侧摆东西，把它们与 list 排进同一行",-1)),o(a,{src:"tabs/08-prefix-suffix"}),t[18]||(t[18]=d("h3",{id:"拦截切换",tabindex:"-1"},[e("拦截切换 "),d("a",{class:"header-anchor",href:"#拦截切换","aria-label":'Permalink to "拦截切换"'},"​")],-1)),t[19]||(t[19]=d("p",null,"受控下 value-change 只是意图，宿主校验不过就不写回 value，标签页原地不动",-1)),o(a,{src:"tabs/09-guard"}),t[20]||(t[20]=d("h3",{id:"动态增删",tabindex:"-1"},[e("动态增删 "),d("a",{class:"header-anchor",href:"#动态增删","aria-label":'Permalink to "动态增删"'},"​")],-1)),t[21]||(t[21]=d("p",null,"标签清单归宿主维护；关掉当前这页时把选中值挪到相邻一项，全关完选中值是 null",-1)),o(a,{src:"tabs/10-dynamic"}),t[22]||(t[22]=d("h3",{id:"可滚动的标签栏",tabindex:"-1"},[e("可滚动的标签栏 "),d("a",{class:"header-anchor",href:"#可滚动的标签栏","aria-label":'Permalink to "可滚动的标签栏"'},"​")],-1)),t[23]||(t[23]=d("p",null,"标签多到一行放不下时，把 list 装进作者自建的横滚容器，两端各摆一个滚动按钮",-1)),o(a,{src:"tabs/11-scrollable"}),t[24]||(t[24]=d("h3",{id:"切换后滚进视野",tabindex:"-1"},[e("切换后滚进视野 "),d("a",{class:"header-anchor",href:"#切换后滚进视野","aria-label":'Permalink to "切换后滚进视野"'},"​")],-1)),t[25]||(t[25]=d("p",null,"每个标签都带 data-value 身份标记，选中值一变就按它取到那个标签，滚到视口正中",-1)),o(a,{src:"tabs/12-active-into-view"}),t[26]||(t[26]=d("h3",{id:"标签栏摆在哪一边",tabindex:"-1"},[e("标签栏摆在哪一边 "),d("a",{class:"header-anchor",href:"#标签栏摆在哪一边","aria-label":'Permalink to "标签栏摆在哪一边"'},"​")],-1)),t[27]||(t[27]=d("p",null,"root 按书写顺序渲染子节点：把面板写在 list 前面，标签栏就落到内容之后，基线换到另一边",-1)),o(a,{src:"tabs/13-placement"}),t[28]||(t[28]=d("h3",{id:"拖拽换位",tabindex:"-1"},[e("拖拽换位 "),d("a",{class:"header-anchor",href:"#拖拽换位","aria-label":'Permalink to "拖拽换位"'},"​")],-1)),t[29]||(t[29]=d("p",null,"整个标签都是拖动源：按住往旁边拖，落点画成一条线、被拖的标签原地不动；也可以聚焦标签带后按 Alt + 左右键挪一位（竖排是 Alt + 上下键），到首末就不动。库不拥有标签序，只报一次重排好的新顺序连同读屏播报，照它写回数组归使用者",-1)),o(a,{src:"tabs/14-reorder"}),t[30]||(t[30]=c('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-tabs&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhTabsContent</code> <code>XhTabsList</code> <code>XhTabsLiveRegion</code> <code>XhTabsRoot</code> <code>XhTabsTabDragTrigger</code> <code>XhTabsTrigger</code></td></tr><tr><td>组合式函数</td><td><code>useTabs</code></td></tr><tr><td>状态机</td><td><code>tabsMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/tabs.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;tabs&quot;</code>：<code>root</code> · <strong><code>list</code></strong> · <strong><code>trigger</code></strong> · <strong><code>content</code></strong> · <code>tab-drag-trigger</code> · <code>live-region</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>collection</code></td><td><code>TabsNode[]</code></td><td></td><td>条目数据，标签文本与禁用的事实源。给了它，trigger 部件只需报 value。 缺省即回到「文本与禁用都写在 trigger 上」的老路。</td></tr><tr><td><code>value</code></td><td><code>string | null</code></td><td></td><td>选中值。给定即受控：内部不再自改，只发 onValueChange。</td></tr><tr><td><code>defaultValue</code></td><td><code>string | null</code></td><td></td><td></td></tr><tr><td><code>orientation</code></td><td><code>Orientation</code></td><td></td><td>方向键轴向，默认 horizontal；不同轴的方向键放行给页面滚动与读屏。</td></tr><tr><td><code>dir</code></td><td><code>Direction</code></td><td></td><td>文字方向，默认 ltr；只影响水平轴上 ArrowLeft/ArrowRight 的前后语义。</td></tr><tr><td><code>activationMode</code></td><td><code>TabsActivationMode</code></td><td></td><td>方向键移动焦点时是否顺带切换选中，默认 automatic。</td></tr><tr><td><code>loop</code></td><td><code>boolean</code></td><td></td><td>方向键走到尽头是否回绕，默认 true。</td></tr><tr><td><code>variant</code></td><td><code>TabsVariant</code></td><td></td><td>形态：line / card / segment，决定选中态怎么画。缺省是 line。</td></tr><tr><td><code>tone</code></td><td><code>Tone</code></td><td></td><td>语气：brand / neutral / success / warning / danger / info，决定用哪族颜色。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg。</td></tr><tr><td><code>reorderable</code></td><td><code>boolean</code></td><td></td><td>标签可以拖着换位。整个标签都是拖动源，不另出把手。 顺序不进机器：collection 是 prop，库没有一份自己的标签序可写，只发 onTabMove。</td></tr><tr><td><code>onTabMove</code></td><td><code>(details: TabsMoveDetails) =&gt; void</code></td><td></td><td></td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;TabsTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>onValueChange</code></td><td><code>(details: TabsValueChangeDetails) =&gt; void</code></td><td></td><td>value 变化意图回调；受控时是唯一出口，非受控随内部写入一并通知。</td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>value-change</code></td><td><code>TabsValueChangeDetails</code></td><td>选中值变化；detail 为 <code>{ value: string | null }</code></td></tr><tr><td><code>tab-move</code></td><td><code>TabsMoveDetails</code></td><td>标签换了位；detail 为 <code>{ value, from, to, values }</code>，values 是重排好的整份标签序</td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>对外可见的状态落在 <code>data-state</code> 上，写样式与断言都读它：</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>trigger</code></td><td>&#39;active&#39; | &#39;inactive&#39;</td></tr><tr><td><code>content</code></td><td>&#39;active&#39; | &#39;inactive&#39;</td></tr></tbody></table><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>idle</code></p><p><strong>事件</strong>：<code>VALUE.SET</code> · <code>TRIGGER.SELECT</code> · <code>TRIGGER.FOCUS</code> · <code>TRIGGER.NAVIGATE</code> · <code>LIST.BLUR</code> · <code>TAB_DRAG.START</code> · <code>TAB_DRAG.MOVE</code> · <code>TAB_DRAG.END</code> · <code>TAB_DRAG.CANCEL</code> · <code>TAB.MOVE_BY</code></p><p><strong>判据</strong>：<code>isAutomatic</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useTabs</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>string | null</code></td><td></td></tr><tr><td><code>collection</code></td><td><code>readonly TabsNodeMeta[]</code></td><td>collection 推出的条目元信息，按数据顺序排列；没给 collection 即空数组。</td></tr><tr><td><code>focusedValue</code></td><td><code>string | null</code></td><td>焦点在组外时为 null。</td></tr><tr><td><code>dropTarget</code></td><td><code>DropTarget | null</code></td><td>此刻的落点；松手就落在这儿。没落在任何标签上时是 null。</td></tr><tr><td><code>announcement</code></td><td><code>string</code></td><td>读屏播报文本。渲进 live-region，不进视觉版面。</td></tr><tr><td><code>setValue</code></td><td><code>(next: string | null) =&gt; void</code></td><td>传 null 清空选中：context.value 与受控 value 都能表达&quot;无选中&quot;，写入侧同样收得下。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getListProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTriggerProps</code></td><td><code>(props: TabsTriggerProps) =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getContentProps</code></td><td><code>(props: TabsContentProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTabDragTriggerProps</code></td><td><code>(props: TabsTriggerProps) =&gt; T[&#39;element&#39;]</code></td><td>标签拖动把手。触屏那一路唯一的入口，不占 Tab 位。 常挂即可：reorderable 关着或这个标签禁用时它自报 data-disabled、也不再让出滚动， 渲了不会错。按拖不拖得动来决定渲不渲，会让 DOM 结构随状态变。</td></tr><tr><td><code>getLiveRegionProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/tabs/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>ArrowRight</code> / <code>ArrowDown</code></td><td>focus in list, 按键与 orientation 同轴</td><td>焦点移到下一个 trigger（禁用项跳过、尽头按 loop 回绕）；automatic 模式顺带切换选中</td></tr><tr><td><code>ArrowLeft</code> / <code>ArrowUp</code></td><td>focus in list, 按键与 orientation 同轴</td><td>焦点移到上一个 trigger；automatic 模式顺带切换选中</td></tr><tr><td><code>Home</code></td><td>focus in list</td><td>焦点移到首个可停留 trigger</td></tr><tr><td><code>End</code></td><td>focus in list</td><td>焦点移到末个可停留 trigger</td></tr><tr><td><code>Enter</code> / <code>Space</code></td><td>focus in trigger, not disabled</td><td>把选中切到焦点所在 trigger（manual 模式的确认键）</td></tr><tr><td><code>Tab</code> / <code>Shift+Tab</code></td><td>focus in list</td><td>整组只有锚点 trigger 留在 Tab 序列内，一次 Tab 进出；无锚点时由 list 兜底，焦点进来后转投锚点 trigger（即选中项），锚点缺席或被禁用才落首个可停留项</td></tr><tr><td><code>Alt+ArrowLeft</code> / <code>Alt+ArrowRight</code> / <code>Alt+ArrowUp</code> / <code>Alt+ArrowDown</code></td><td>focus in list, reorderable 开着, 按键与 orientation 同轴</td><td>把焦点标签在标签带里往前 / 往后挪一位，按一下就是一次完整提交，不进拖动态；横轴跟着文字方向翻、rtl 下左右两键对调，竖排的上下两键不对调；已是首位 / 末位就不动，也不回绕；标签序不进库，只报一次重排好的新顺序。裸方向键仍是导航、Enter/Space 仍是确认</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>list</code></td><td><code>aria-orientation</code></td><td>props.orientation</td></tr><tr><td><code>list</code></td><td><code>role</code></td><td>&#39;tablist&#39;</td></tr><tr><td><code>trigger</code></td><td><code>aria-controls</code></td><td><code>content</code> 部件的 id</td></tr><tr><td><code>trigger</code></td><td><code>aria-disabled</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>trigger</code></td><td><code>aria-selected</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>trigger</code></td><td><code>role</code></td><td>&#39;tab&#39;</td></tr><tr><td><code>content</code></td><td><code>aria-labelledby</code></td><td><code>trigger</code> 部件的 id</td></tr><tr><td><code>content</code></td><td><code>role</code></td><td>&#39;tabpanel&#39;</td></tr><tr><td><code>tab-drag-trigger</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>live-region</code></td><td><code>aria-atomic</code></td><td>&#39;true&#39;</td></tr><tr><td><code>live-region</code></td><td><code>aria-live</code></td><td>&#39;polite&#39;</td></tr><tr><td><code>live-region</code></td><td><code>role</code></td><td>&#39;status&#39;</td></tr></tbody></table><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/tabs.css</code> 按部件选择：<code>[data-scope=&quot;tabs&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-orientation</code></td><td>props.orientation</td></tr><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-tone</code></td><td>props.tone</td></tr><tr><td><code>root</code></td><td><code>data-variant</code></td><td>props.variant</td></tr><tr><td><code>trigger</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>trigger</code></td><td><code>data-draggable</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>trigger</code></td><td><code>data-dragging</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>trigger</code></td><td><code>data-drop</code></td><td>&#39;before&#39; | &#39;after&#39;</td></tr><tr><td><code>trigger</code></td><td><code>data-state</code></td><td>&#39;active&#39; | &#39;inactive&#39;</td></tr><tr><td><code>content</code></td><td><code>data-state</code></td><td>&#39;active&#39; | &#39;inactive&#39;</td></tr><tr><td><code>tab-drag-trigger</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>tab-drag-trigger</code></td><td><code>data-dragging</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-tabs-content-fg</code> · <code>--xh-tabs-content-py</code> · <code>--xh-tabs-drag-fg</code> · <code>--xh-tabs-drag-fg-active</code> · <code>--xh-tabs-drag-fg-disabled</code> · <code>--xh-tabs-drag-grip-long</code> · <code>--xh-tabs-drag-grip-short</code> · <code>--xh-tabs-drag-radius</code> · <code>--xh-tabs-drag-size</code> · <code>--xh-tabs-dragging-opacity</code> · <code>--xh-tabs-drop-fg</code> · <code>--xh-tabs-drop-line</code> · <code>--xh-tabs-gap</code> · <code>--xh-tabs-list-bg</code> · <code>--xh-tabs-list-border</code> · <code>--xh-tabs-list-gap</code> · <code>--xh-tabs-list-p</code> · <code>--xh-tabs-list-radius</code> · <code>--xh-tabs-trigger-bg</code> · <code>--xh-tabs-trigger-bg-active</code> · <code>--xh-tabs-trigger-bg-active-hover</code> · <code>--xh-tabs-trigger-bg-hover</code> · <code>--xh-tabs-trigger-border</code> · <code>--xh-tabs-trigger-border-active</code> · <code>--xh-tabs-trigger-fg</code> · <code>--xh-tabs-trigger-fg-active</code> · <code>--xh-tabs-trigger-font-size</code> · <code>--xh-tabs-trigger-font-weight</code> · <code>--xh-tabs-trigger-gap</code> · <code>--xh-tabs-trigger-h</code> · <code>--xh-tabs-trigger-px</code> · <code>--xh-tabs-trigger-radius</code> · <code>--xh-tabs-trigger-shadow-active</code></p><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>状态切换走 <code>transition</code>。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>与<a href="./card">卡片</a>配合；标签多到一行放不下时把标签栏装进自建的横滚容器。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>标签数控制在七个以内，超过就该换成<a href="./side-nav">侧栏导航</a>。</li><li>把当前标签写进地址，刷新后才回得到原处。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>标签页里再套标签页：用户分不清哪一层在切。</li><li>面板高度随内容剧烈变化，切换时整页跳动。</li></ul>',45))])}const P=l(h,[["render",g]]);export{v as __pageData,P as default};
